const LESSONS = [
  {id:1,title:'Deine Lohnabrechnung lesen',subtitle:'Was steht drauf – und wozu?',time:'3 Min.',sources:[0],memory:'Die Lohnabrechnung zeigt den Weg vom vereinbarten Lohn zum ausbezahlten Betrag.',html:`
    <h2>Dein Lohn auf einen Blick</h2><p>Einmal im Monat bekommst du deine Lohnabrechnung. Sie zeigt, was du verdient hast, was abgezogen wird und wie viel Geld du erhältst.</p>
    <div class="table-wrap"><table><thead><tr><th>Element</th><th>Bedeutung</th></tr></thead><tbody>
    <tr><td>Personen & Zeitraum</td><td>Dein Name, Lehrbetrieb und Abrechnungsmonat</td></tr><tr><td>Grundlohn & Zulagen</td><td>Vertraglicher Lohn, dazu zum Beispiel ein ausbezahlter 13. Monatslohn</td></tr><tr><td><strong>Bruttolohn</strong></td><td>Lohn vor den Abzügen</td></tr><tr><td>Abzüge</td><td>Zum Beispiel Beiträge an Sozialversicherungen</td></tr><tr><td><strong>Nettolohn</strong></td><td>Lohn nach den entsprechenden Abzügen</td></tr><tr><td>Spesen / Verrechnungen</td><td>Zum Beispiel Geschäftsfahrten zurückerstatten oder einen Lohnvorschuss abziehen</td></tr><tr><td><strong>Auszahlungsbetrag</strong></td><td>Das wird tatsächlich überwiesen</td></tr></tbody></table></div>
    <div class="example"><div class="example-label">Zum Beispiel</div><p>Dein Nettolohn ist CHF 990. Du bekommst CHF 25 für eine Geschäftsreise zurück. Ohne weitere Verrechnungen landen <strong>CHF 1’015</strong> auf deinem Konto.</p></div><p><strong>Spesen sind eine Rückerstattung von Geschäftsausgaben.</strong> Deshalb können Nettolohn und Auszahlungsbetrag verschieden sein.</p>`},
  {id:2,title:'Wer bezahlt welche Abzüge?',subtitle:'Dein Anteil und der Anteil des Lehrbetriebs.',time:'4 Min.',sources:[0,1,2,3,4,9],memory:'Nur dein Arbeitnehmeranteil wird vom Lohn abgezogen. Den Arbeitgeberanteil bezahlt der Betrieb zusätzlich.',html:`
    <h2>Du und dein Lehrbetrieb</h2><p>Du bist der <strong>Arbeitnehmer</strong>, dein Lehrbetrieb ist der <strong>Arbeitgeber</strong>. Bei verschiedenen Versicherungen teilen sich beide die Beiträge.</p>
    <p class="note"><strong>Für dich mit 16:</strong> AHV/IV/EO und ALV werden noch nicht abgezogen. Die Beitragspflicht beginnt am 1. Januar des Jahres, in dem du 18 wirst – also nach dem Jahr deines 17. Geburtstags.</p>
    <div class="table-wrap"><table><thead><tr><th>Versicherung</th><th>Du</th><th>Betrieb</th></tr></thead><tbody><tr><td>AHV · Alter / Hinterlassene</td><td>4,35 %</td><td>4,35 %</td></tr><tr><td>IV · Invalidität / Eingliederung</td><td>0,70 %</td><td>0,70 %</td></tr><tr><td>EO · Erwerbsersatz, z. B. bei Dienst</td><td>0,25 %</td><td>0,25 %</td></tr><tr><td><strong>AHV / IV / EO zusammen</strong></td><td><strong>5,30 %</strong></td><td><strong>5,30 %</strong></td></tr><tr><td>ALV · Arbeitslosigkeit</td><td>1,10 %</td><td>1,10 %</td></tr></tbody></table></div>
    <p class="calc-note">Sätze 2026 für beitragspflichtige Arbeitnehmende. ALV bis CHF 148’200 Jahreslohn. AHV/IV/EO + ALV = 6,4 % je Seite.</p>
    <details class="explain-check glossary"><summary>Wofür stehen die Abkürzungen?</summary><ul><li><strong>AHV:</strong> Alters- und Hinterlassenenversicherung – Leistungen im Alter und nach dem Tod einer versicherten Person für Hinterlassene.</li><li><strong>IV:</strong> Invalidenversicherung – vor allem Eingliederung bei länger dauernden gesundheitlichen Einschränkungen, unter Voraussetzungen auch Renten.</li><li><strong>EO:</strong> Erwerbsersatzordnung – Erwerbsersatz etwa bei Militärdienst, Mutterschaft oder Urlaub des anderen Elternteils.</li><li><strong>ALV:</strong> Arbeitslosenversicherung – Leistungen insbesondere bei Arbeitslosigkeit.</li></ul></details>
    <h2>Weitere Versicherungen</h2><ul><li><strong>BU – Berufsunfallversicherung:</strong> Für Unfälle bei der Arbeit. Die Prämie trägt der Betrieb.</li><li><strong>NBU – Nichtberufsunfallversicherung:</strong> Für Freizeitunfälle. Grundsätzlich zahlst du, der Betrieb darf die Prämie übernehmen. Schutz über den Betrieb ab acht Wochenstunden beim gleichen Arbeitgeber. Der Satz variiert.</li><li><strong>BVG / Pensionskasse:</strong> Beide bezahlen; der Betrieb insgesamt mindestens so viel wie seine Arbeitnehmer zusammen. Obligatorisch frühestens ab dem Jahr des 18. Geburtstags bei mehr als CHF 22’680 Jahreslohn (2026), zunächst für Tod und Invalidität. Alterssparen ab dem Jahr des 25. Geburtstags.</li><li><strong>KTG – Krankentaggeldversicherung:</strong> Falls versichert. Aufteilung gemäss den geltenden vertraglichen Regeln.</li></ul>
    <div class="example"><div class="example-label">Merke dir den Zeitpunkt</div><p>Du wirst im September 2028 18. Deine AHV/IV/EO- und ALV-Beiträge starten bereits am <strong>1. Januar 2028</strong>. NBU-Abzüge können schon mit 16 anfallen.</p></div>`},
  {id:3,title:'Brutto ist nicht gleich netto',subtitle:'So rechnest du deinen Nettolohn aus.',time:'3 Min.',sources:[0,1,3],memory:'Bruttolohn minus Abzüge ergibt den Nettolohn. Für dein Budget zählt, was danach noch zu bezahlen ist.',html:`
    <h2>Vorher und nachher</h2><p><strong>Brutto</strong> ist dein Lohn vor den Abzügen. <strong>Netto</strong> bleibt nach den Abzügen übrig.</p><div class="example"><div class="formula">Bruttolohn − Abzüge = Nettolohn</div></div>
    <h2>Zwei Lernbeispiele</h2><p>Wir nehmen CHF 1’000 Bruttolohn und <strong>1 % NBU</strong> an. Es gibt keine weiteren Abzüge und keine Spesen. Der NBU-Satz ist eine Annahme.</p>
    <div class="table-wrap"><table><thead><tr><th>Position</th><th>Mit 16</th><th>AHV-pflichtig</th></tr></thead><tbody><tr><td>Brutto</td><td>CHF 1’000</td><td>CHF 1’000</td></tr><tr><td>AHV / IV / EO · 5,3 %</td><td>CHF 0</td><td>− CHF 53</td></tr><tr><td>ALV · 1,1 %</td><td>CHF 0</td><td>− CHF 11</td></tr><tr><td>NBU · angenommen 1 %</td><td>− CHF 10</td><td>− CHF 10</td></tr><tr><td><strong>Netto</strong></td><td><strong>CHF 990</strong></td><td><strong>CHF 926</strong></td></tr></tbody></table></div>
    <h2>Prozente sind kein Hexenwerk</h2><p>CHF 1’000 × 5,3 ÷ 100 = CHF 53.</p><p class="note">Nettolohn ist nicht gleich frei verfügbares Geld. Zum Beispiel müssen ÖV, Mittagessen, Handy und Rückstellungen noch in dein Budget.</p>`},
  {id:4,title:'Wie Schulden entstehen',subtitle:'Ursachen und Folgen auseinanderhalten.',time:'3 Min.',sources:[12],memory:'Schulden können durch Ausgabenentscheidungen und durch schwierige Lebensereignisse entstehen.',html:`
    <h2>Was sind eigentlich Schulden?</h2><p>Du hast Schulden, wenn du jemandem Geld schuldest. Besonders schwierig wird es, wenn du fällige Rechnungen oder Rückzahlungen nicht mehr bezahlen kannst.</p>
    <h2>Mögliche Ursachen</h2><ul><li><strong>Ausgaben höher als Einnahmen:</strong> Du gibst CHF 1’100 aus, hast aber nur CHF 900.</li><li><strong>Überblick fehlt:</strong> Viele kleine Abos und Raten summieren sich.</li><li><strong>Einkommen fällt weg:</strong> Zum Beispiel durch Arbeitslosigkeit.</li><li><strong>Unerwartete Kosten:</strong> Eine dringende Zahnarztrechnung.</li><li><strong>Druck oder problematisches Verhalten:</strong> Mithalten wollen, Glücksspiel oder unkontrolliertes Kaufen.</li></ul>
    <h2>Mögliche Folgen</h2><p>Zusätzliche Zinsen und berechtigte Kosten können dazukommen. Betreibungen und unter bestimmten Voraussetzungen Pfändungen sind möglich. Auch die Wohnungssuche kann schwieriger werden. Stress, Scham oder Streit können zusätzlich belasten.</p>
    <div class="example"><div class="example-label">Ursache oder Folge?</div><p><strong>Arbeitslosigkeit</strong> kann eine Ursache sein. Eine <strong>Betreibung wegen unbezahlter Rechnungen</strong> ist eine mögliche Folge.</p></div><p><strong>Betreibung</strong> heisst: Eine Geldforderung wird mit einem staatlichen Verfahren durchgesetzt. Bei einer <strong>Pfändung</strong> werden pfändbare Vermögenswerte oder Lohnanteile zur Schuldentilgung herangezogen; notwendige Grundlagen bleiben geschützt.</p><p>Bei Geldproblemen hilft es, früh Unterstützung zu holen. Schulden sind kein Massstab für den Wert eines Menschen.</p>`},
  {id:5,title:'Privatkonkurs: der Ablauf',subtitle:'Was Gericht und Konkursamt machen.',time:'4 Min.',sources:[5,6,7,10,11],memory:'Privatkonkurs ist ein geregeltes Verfahren. Die übrigen Schulden verschwinden dadurch nicht automatisch.',html:`
    <h2>Ein Verfahren bei Zahlungsunfähigkeit</h2><p>Wer fällige Verpflichtungen nicht mehr erfüllen kann, ist zahlungsunfähig. Ein Privatkonkurs wird vom Gericht geprüft. Grundlage ist insbesondere <strong>Art. 191 SchKG</strong>.</p>
    <p><strong>SchKG</strong> bedeutet Bundesgesetz über Schuldbetreibung und Konkurs. Zuständig ist grundsätzlich das Konkursgericht am Wohnsitz. Es prüft unter anderem, ob eine einvernehmliche Schuldenbereinigung noch möglich ist. Auch ein künftig tragfähiges Budget und die Finanzierung des Verfahrens sind wichtig. Es gibt keine automatische Bewilligung nur wegen hoher Schulden.</p>
    <ol><li><strong>Situation klären:</strong> Einkommen, Vermögen und Schulden erfassen; eine Einigung mit den Gläubigern prüfen.</li><li><strong>Gesuch stellen:</strong> Beim Gericht die Zahlungsunfähigkeit erklären (Insolvenzerklärung).</li><li><strong>Prüfung:</strong> Voraussetzungen und Finanzierung der Verfahrenskosten klären; Bewilligung erfolgt nicht automatisch.</li><li><strong>Konkurs eröffnen:</strong> Das Konkursamt übernimmt die Abwicklung.</li><li><strong>Vermögen verwerten:</strong> Pfändbare Werte werden zu Geld gemacht; geschützte notwendige Gegenstände bleiben.</li><li><strong>Geld verteilen:</strong> Gläubiger erhalten nach gesetzlicher Rangordnung Geld. Für offene Restforderungen gibt es Konkursverlustscheine.</li></ol>
    <div class="example"><div class="example-label">Drei Wörter für den Test</div><p><strong>Schuldner:</strong> schuldet Geld.<br><strong>Gläubiger:</strong> hat eine Forderung.<br><strong>Verlustschein:</strong> hält die ungedeckte Forderung fest.</p></div>
    <p>Alte Forderungen können bei neuem Vermögen wieder durchgesetzt werden. Dazu kann auch ein <strong>Einkommen gehören, mit dem Vermögen gebildet werden könnte</strong>. Unter den Voraussetzungen kann man sich mit dem ausdrücklich so begründeten Rechtsvorschlag <strong>«kein neues Vermögen»</strong> wehren. Neue Schulden sind davon nicht geschützt.</p>
    <p class="note">Der Kostenvorschuss beim Gericht deckt nicht automatisch das ganze Verfahren. Weitere Kosten können beim Konkursamt entstehen. Wird der Konkurs mangels Aktiven eingestellt, besteht der besondere Schutz «kein neues Vermögen» nicht. Bei echten Geldproblemen zuerst eine Schuldenberatung beiziehen.</p>
    <p class="note"><strong>Stand 27.10.2026:</strong> Ein neues Sanierungsverfahren mit möglicher Restschuldbefreiung ist beschlossen, aber noch nicht in Kraft. Hier lernst du das geltende Recht.</p>`},
  {id:6,title:'Privatkonkurs: Vor- und Nachteile',subtitle:'Entlastung verstehen, Grenzen kennen.',time:'3 Min.',sources:[5,6,11],memory:'Ein Privatkonkurs kann Luft verschaffen. Er bedeutet weder einen kostenlosen noch einen schuldenfreien Neustart.',html:`
    <h2>Was kann entlasten?</h2><ul><li>Bisherige Betreibungen werden grundsätzlich aufgehoben; eine Lohnpfändung kann enden.</li><li>Die Abwicklung erfolgt geordnet in einem Verfahren.</li><li>Für Forderungen in Konkursverlustscheinen laufen keine weiteren Zinsen.</li></ul>
    <h2>Welche Nachteile gibt es?</h2><ul><li>Verwertbares Vermögen geht verloren.</li><li>Das Verfahren kostet Geld und wird öffentlich bekannt gemacht.</li><li>Offene Restschulden bleiben bestehen; bei neuem Vermögen können Forderungen wieder durchgesetzt werden.</li><li>Neue Schulden können wieder zu Betreibungen führen.</li></ul>
    <div class="example"><div class="example-label">So klingt eine gute Testantwort</div><p>«Ein Vorteil ist die mögliche Entlastung von einer Lohnpfändung. Ein Nachteil ist, dass verwertbares Vermögen verkauft wird und die Restschulden bestehen bleiben.»</p></div>`},
  {id:7,title:'Die Schuldenspirale erkennen',subtitle:'Warum neue Schulden das Problem vergrössern können.',time:'3 Min.',sources:[12],memory:'Raten belegen schon heute einen Teil deines zukünftigen Einkommens.',html:`
    <h2>Wenn eins zum anderen führt</h2><p>Eine Schuldenspirale entsteht, wenn du neue Schulden machst, um alte Verpflichtungen zu bezahlen – und die Belastung immer grösser wird.</p>
    <ol><li>Du kaufst ein Handy auf Raten.</li><li>Die monatliche Rate fehlt dir bei anderen Rechnungen.</li><li>Du leihst weiteres Geld, um diese Rechnungen zu zahlen.</li><li>Jetzt musst du mehrere Beträge zurückzahlen. Zinsen und zusätzliche Kosten können dazukommen.</li></ol>
    <h2>Woran erkennst du die Gefahr?</h2><p>Du verlierst den Überblick, öffnest Rechnungen nicht mehr oder hast keine Reserve für Unerwartetes. Dein zukünftiger Lohn ist schon verplant.</p>
    <div class="example"><div class="example-label">Ein sinnvoller erster Schritt</div><p>Alle Rechnungen öffnen, Fristen notieren und Einnahmen sowie Ausgaben auflisten. Früh die Rechnungsstelle oder eine Schuldenberatung kontaktieren, statt einfach den nächsten Kredit aufzunehmen.</p></div><p>Unterstützung findest du bei der <a href="https://www.schulden-zh.ch/beratung/angebot/" target="_blank" rel="noopener noreferrer"><u>Schuldenberatung Kanton Zürich ↗</u></a>. Auch eine vertraute erwachsene Person kann beim ersten Schritt helfen.</p>`},
  {id:8,title:'Typische Schuldenfallen',subtitle:'Kleine Beträge, grosse Wirkung.',time:'3 Min.',sources:[12],memory:'Prüfe die Gesamtkosten und lege für unregelmässige Rechnungen jeden Monat etwas zurück.',html:`
    <h2>Diese Fallen solltest du kennen</h2><div class="table-wrap"><table><thead><tr><th>Falle</th><th>Was leicht vergessen geht</th></tr></thead><tbody><tr><td>Jetzt kaufen, später bezahlen</td><td>Das Geld muss bei Fälligkeit trotzdem da sein.</td></tr><tr><td>Mehrere Ratenkäufe</td><td>Viele kleine Raten ergeben eine grosse Monatssumme.</td></tr><tr><td>Kreditkarten-Teilzahlung</td><td>Auf offene Beträge können hohe Zinsen anfallen.</td></tr><tr><td>Abos, In-App-Käufe, Glücksspiel</td><td>Viele Einzelbeträge können das Budget sprengen.</td></tr><tr><td>Leasing</td><td>Die Monatsrate ist nur ein Teil der Kosten.</td></tr><tr><td>Jahresrechnungen vergessen</td><td>Ohne Rückstellungen fehlt das Geld bei Fälligkeit.</td></tr></tbody></table></div>
    <div class="example"><div class="example-label">Einfach vorausplanen</div><p>Ein Jahresabo kostet CHF 240. Lege jeden Monat <strong>CHF 20</strong> zurück: 240 ÷ 12 = 20.</p></div>
    <h2>Dein kurzer Geld-Check</h2><ul><li>Mit dem Nettolohn budgetieren.</li><li>Notwendige Ausgaben zuerst einplanen.</li><li>Rückstellungen und eine Reserve berücksichtigen.</li><li>Vor einem Kauf alle laufenden Verpflichtungen zusammenzählen.</li></ul>`},
  {id:9,title:'Was Leasing wirklich kostet',subtitle:'Gesamtkosten statt nur Monatsrate.',time:'4 Min.',sources:[8,13],memory:'Leasing heisst nutzen und bezahlen. Die Rate ist nicht der ganze Preis, und Eigentum entsteht nicht automatisch.',html:`
    <h2>Nutzen, ohne automatisch Eigentümer zu werden</h2><p>Beim Leasing nutzt du einen Gegenstand gegen regelmässige Raten. Das Auto gehört währenddessen grundsätzlich der Leasinggesellschaft. Eine spätere Übernahme braucht eine eigene Regelung.</p><p class="note">Autoleasing ist hier ein Lernbeispiel für später. Es zeigt dir, wie langfristige Zahlungsverpflichtungen wirken.</p>
    <h2>Die Rechnung hinter der Werbung</h2><p>Angenommen: 48 Monate, CHF 250 Rate, CHF 300 Betriebskosten pro Monat und CHF 3’000 einmalige Sonderzahlung. Diese Zahlung ist keine rückzahlbare Kaution.</p>
    <div class="table-wrap"><table><thead><tr><th>Position</th><th>Über 4 Jahre</th></tr></thead><tbody><tr><td>48 × CHF 250 Raten</td><td>CHF 12’000</td></tr><tr><td>48 × CHF 300 Betriebskosten</td><td>CHF 14’400</td></tr><tr><td>Einmalige Sonderzahlung</td><td>CHF 3’000</td></tr><tr><td><strong>Gesamtausgaben</strong></td><td><strong>CHF 29’400</strong></td></tr></tbody></table></div>
    <div class="example"><div class="example-label">Durchschnitt pro Monat</div><div class="formula">CHF 29’400 ÷ 48 = CHF 612.50</div><p>Die Werbung zeigt CHF 250. Die angenommene Gesamtbelastung ist viel höher. Eine spätere Übernahme ist nicht enthalten.</p></div>
    <h2>Was bindet dich langfristig?</h2><ul><li>Raten bleiben geschuldet, auch wenn dein Einkommen sinkt.</li><li>Vorzeitig aussteigen kann hohe Nachzahlungen auslösen.</li><li>Mehrkilometer und Schäden können bei Rückgabe extra kosten.</li><li>Versicherung, Treibstoff, Abgaben und Unterhalt kommen dazu; oft wird Vollkasko verlangt.</li></ul>
    <h2>Welche Regeln schützen dich?</h2><p>Für Leasingverträge unter dem <strong>Konsumkreditgesetz (KKG)</strong> gelten Schriftform und Kreditfähigkeitsprüfung. Ein schriftlicher Widerruf ist innerhalb von 14 Tagen ab Erhalt der Vertragskopie möglich.</p><p>Vorzeitige Kündigung ist unter dem KKG mit mindestens 30 Tagen Frist auf Ende einer dreimonatigen Leasingdauer möglich. Die Entschädigung ergibt sich aus der Tabelle im Vertrag. <strong>Kündbar bedeutet deshalb nicht kostenlos kündbar.</strong></p><p class="note"><strong>Mit 16 wichtig:</strong> Ein Konsumkreditvertrag unter dem KKG braucht bei Minderjährigen die schriftliche Zustimmung der gesetzlichen Vertretung, spätestens bei der Unterzeichnung. Das gilt auch für erfasste Leasingverträge.</p>`}
];
const RECALL = {
  1:{goal:'Die Elemente einer Lohnabrechnung erläutern.',prompt:'Erkläre den Weg vom Grundlohn bis zum Betrag auf deinem Konto. Wo kommen Spesen dazu?',model:'Grundlohn und Lohnzulagen ergeben den Bruttolohn. Nach den Abzügen bleibt der Nettolohn. Geschäftsspesen und weitere Verrechnungen verändern den Auszahlungsbetrag. Namen und Abrechnungsmonat gehören ebenfalls auf die Abrechnung.'},
  2:{goal:'Die Beiträge von Arbeitgeber und Arbeitnehmer erläutern.',prompt:'Erkläre, was du und dein Lehrbetrieb bezahlen. Was gilt für dich mit 16, und was ab Beginn der AHV-Pflicht?',model:'Mit 16 noch keine AHV/IV/EO- und ALV-Beiträge, aber zum Beispiel NBU. Ab dem Jahr des 18. Geburtstags tragen Arbeitnehmer und Arbeitgeber je 5,3 % AHV/IV/EO und 1,1 % ALV bis zur Beitragsgrenze. Den Arbeitgeberanteil trägt der Betrieb zusätzlich. BU bezahlt der Betrieb, NBU grundsätzlich der Arbeitnehmer; BVG und gegebenenfalls KTG haben weitere Regeln.'},
  3:{goal:'Den Unterschied zwischen Bruttolohn und Nettolohn erklären.',prompt:'Erkläre brutto und netto. Rechne dann CHF 1’000 brutto minus CHF 74 Abzüge und sage, weshalb du den Rest nicht einfach ausgeben solltest.',model:'Brutto ist vor, netto nach den Abzügen. CHF 1’000 − CHF 74 = CHF 926 netto. Persönliche Ausgaben und Rückstellungen sind davon noch zu bezahlen.'},
  4:{goal:'Mögliche Ursachen und Folgen privater Verschuldung erläutern.',prompt:'Nenne zwei unterschiedliche Ursachen von Schulden und zwei mögliche Folgen. Erkläre je den Zusammenhang.',model:'Zum Beispiel: Einkommensverlust oder unerwartete Ausgaben führen zu einer Budgetlücke. Werden fällige Rechnungen nicht bezahlt, können zusätzliche Kosten und Betreibungen entstehen. Auch Stress ist eine mögliche Folge.'},
  5:{goal:'Ablauf und rechtliche Rahmenbedingungen eines Privatkonkurses erklären.',prompt:'Erkläre den vereinfachten Ablauf. Wer entscheidet, welches Gesetz ist wichtig und was passiert mit ungedeckten Schulden?',model:'Zuerst Situation und Einigungsmöglichkeiten prüfen. Dann Insolvenzerklärung beim Gericht nach Art. 191 SchKG; Voraussetzungen und Kosten werden geprüft. Nach Eröffnung verwertet das Konkursamt pfändbares Vermögen und verteilt den Erlös. Restforderungen bleiben mit Konkursverlustscheinen bestehen.'},
  6:{goal:'Vor- und Nachteile eines Privatkonkurses nennen.',prompt:'Nenne zwei mögliche Vorteile und zwei Nachteile. Weshalb heisst Konkurs nicht automatisch schuldenfrei?',model:'Eine Lohnpfändung kann enden, und die Abwicklung wird gebündelt. Dafür gehen verwertbare Werte verloren und das Verfahren kostet Geld. Ungedeckte Schulden werden nicht automatisch erlassen; bei neuem Vermögen können alte Forderungen wieder durchgesetzt werden.'},
  7:{goal:'Die Gefahren privater Verschuldung erklären.',prompt:'Erkläre die Schuldenspirale am Beispiel eines Handys auf Raten. Wie könntest du die Entwicklung früh unterbrechen?',model:'Die Handy-Rate fehlt bei anderen Rechnungen. Neue Schulden überbrücken die Lücke, erhöhen aber die späteren Rückzahlungen. Budget und Rechnungen prüfen, auf neue Verpflichtungen verzichten und früh Unterstützung holen.'},
  8:{goal:'Typische Verschuldungsfallen nennen.',prompt:'Nenne drei Schuldenfallen. Erkläre bei einer davon, wie du dich schützt.',model:'Zum Beispiel Ratenkäufe, Kreditkarten-Teilzahlung, viele Abos oder fehlende Rückstellungen für Jahresrechnungen. Alle Abos zusammenrechnen und für Jahreskosten monatlich Geld zurücklegen.'},
  9:{goal:'Die langfristige finanzielle Bindung durch Leasing analysieren.',prompt:'Die Werbung nennt CHF 250 pro Monat. Im Lernbeispiel sind es tatsächlich durchschnittlich CHF 612.50. Erkläre den Unterschied und zwei Risiken bei sinkendem Einkommen.',model:'Zur Rate kommen Betriebskosten und die auf die Laufzeit verteilte Sonderzahlung. Weniger Einkommen hebt den Vertrag nicht auf; ein früher Ausstieg kann Nachzahlungen auslösen. Deshalb das zukünftige Budget und alle Kosten prüfen. Eigentum entsteht nicht automatisch.'}
};
const QUESTIONS = [
  {id:'1a',lesson:1,q:'Was zeigt der Bruttolohn auf deiner Lohnabrechnung?',options:['Den Lohn vor den Abzügen','Den Kontostand nach dem Zahltag','Den Lohn nach allen privaten Ausgaben'],answer:0,explain:'Brutto ist der Lohn vor den Abzügen. Netto ist der Lohn nach den Abzügen.'},
  {id:'1b',lesson:1,q:'Netto CHF 990, dazu CHF 25 Geschäftsspesen. Sonst keine Verrechnung. Was wird überwiesen?',options:['CHF 965','CHF 990','CHF 1’015'],answer:2,explain:'990 + 25 = CHF 1’015. Geschäftsspesen sind eine Rückerstattung. Der Auszahlungsbetrag kann deshalb vom Nettolohn abweichen.'},
  {id:'1c',lesson:1,q:'Welche Angabe gehört typischerweise auf eine Lohnabrechnung?',options:['Deine privaten Shopping-Ausgaben','Der Abrechnungsmonat','Dein Sparziel für die Ferien'],answer:1,explain:'Der Abrechnungsmonat zeigt, für welchen Zeitraum du Lohn bekommst. Private Ausgaben gehören in dein Budget.'},
  {id:'2a',lesson:2,q:'Du bist 16. Was gilt für AHV/IV/EO und ALV auf deinem Lehrlingslohn?',options:['Du bezahlst bereits den vollen Anteil','Du bezahlst noch keine dieser Beiträge','Nur dein Arbeitgeberanteil wird abgezogen'],answer:1,explain:'Die Beitragspflicht beginnt am 1. Januar des Jahres, in dem du 18 wirst. Andere Abzüge, zum Beispiel NBU, können vorher anfallen.'},
  {id:'2b',lesson:2,q:'Wer bezahlt die Prämie für Berufsunfälle (BU)?',options:['Nur du','Du und der Betrieb je zur Hälfte','Der Arbeitgeber'],answer:2,explain:'Die Berufsunfallprämie trägt der Arbeitgeber. Die NBU-Prämie für Freizeitunfälle bezahlt grundsätzlich der Arbeitnehmer.'},
  {id:'2c',lesson:2,q:'Du wirst im September 2028 18. Ab wann bezahlst du als Lernender AHV/IV/EO und ALV?',options:['Ab 1. Januar 2028','Erst ab deinem Geburtstag im September 2028','Erst ab 1. Januar 2029'],answer:0,explain:'Entscheidend ist der 1. Januar des Jahres des 18. Geburtstags, nicht der Geburtstag selbst.'},
  {id:'3a',lesson:3,q:'Welche Formel stimmt?',options:['Nettolohn + private Ausgaben = Bruttolohn','Bruttolohn − Abzüge = Nettolohn','Bruttolohn + Abzüge = Nettolohn'],answer:1,explain:'Abzüge werden vom Bruttolohn abgezogen. Spesen und weitere Verrechnungen können danach den Auszahlungsbetrag verändern.'},
  {id:'3b',lesson:3,q:'Ein AHV-pflichtiger Lernender verdient CHF 1’000 brutto. Abzüge: 5,3 % AHV/IV/EO, 1,1 % ALV, angenommene 1 % NBU. Wie viel netto?',options:['CHF 936','CHF 990','CHF 926'],answer:2,explain:'CHF 53 + CHF 11 + CHF 10 = CHF 74 Abzüge. 1’000 − 74 = CHF 926. Weitere Abzüge sind in diesem Beispiel ausgeschlossen.'},
  {id:'3c',lesson:3,q:'Ist dein gesamter Nettolohn automatisch frei für Shopping und Freizeit?',options:['Nein, laufende Kosten und Rückstellungen müssen noch ins Budget','Ja, alle persönlichen Rechnungen sind bereits bezahlt','Ja, solange du noch in der Lehre bist'],answer:0,explain:'Mit dem Nettolohn musst du zum Beispiel ÖV, Essen, Handy oder andere vereinbarte Kosten bezahlen. Plane auch Rückstellungen ein.'},
  {id:'4a',lesson:4,q:'Was ist eine mögliche Ursache privater Verschuldung?',options:['Eine unerwartete Rechnung bei fehlender Reserve','Jede Rechnung sofort bezahlen','Ein ausgeglichenes Budget einhalten'],answer:0,explain:'Unerwartete Ausgaben oder Einkommensverluste können zu Schulden beitragen. Nicht nur das Kaufverhalten spielt eine Rolle.'},
  {id:'4b',lesson:4,q:'Was ist eine mögliche Folge unbezahlter Schulden?',options:['Automatisch mehr Lohn','Eine Betreibung','Alle Schulden verschwinden'],answer:1,explain:'Offene Forderungen können zu Betreibungen führen. Auch Stress und zusätzliche Kosten sind mögliche Folgen.'},
  {id:'4c',lesson:4,q:'CHF 900 stehen dir zur Verfügung, du gibst jeden Monat CHF 1’100 aus. Was fehlt monatlich?',options:['CHF 100','CHF 1’100','CHF 200'],answer:2,explain:'1’100 − 900 = CHF 200. Ohne Anpassung oder zusätzliche Einnahmen entsteht jeden Monat eine neue Lücke.'},
  {id:'5a',lesson:5,q:'Wer entscheidet über die Eröffnung eines Privatkonkurses?',options:['Das Gericht','Der Arbeitgeber','Die Person allein durch einen Brief an ihre Bank'],answer:0,explain:'Das Gericht prüft das Gesuch. Nach der Eröffnung wickelt das Konkursamt das Verfahren ab.'},
  {id:'5b',lesson:5,q:'Was ist ein Gläubiger?',options:['Eine Person, die ihre Rechnungen vergessen hat','Eine Person oder Firma, die Geld zugut hat','Die Stelle, die deinen Lehrlingslohn berechnet'],answer:1,explain:'Der Gläubiger hat eine Forderung. Der Schuldner schuldet ihm Geld.'},
  {id:'5c',lesson:5,q:'Was hält ein Konkursverlustschein fest?',options:['Den Kontostand nach dem Zahltag','Dass alle Schulden erlassen wurden','Den ungedeckten Teil einer Forderung'],answer:2,explain:'Die offene Forderung wird festgehalten. Ein Verlustschein ist kein automatischer Schuldenerlass.'},
  {id:'6a',lesson:6,q:'Welcher Satz zum heutigen Privatkonkurs stimmt?',options:['Die Restschulden werden immer gelöscht','Er kann entlasten, aber Restschulden bleiben grundsätzlich bestehen','Er ist kostenlos'],answer:1,explain:'Ein Konkurs kann zum Beispiel eine Lohnpfändung beenden. Restschulden bleiben bestehen und verwertbares Vermögen wird verkauft.'},
  {id:'6b',lesson:6,q:'Was ist ein möglicher Nachteil eines Privatkonkurses?',options:['Verwertbares Vermögen wird verkauft','Es gibt keine Verfahrenskosten','Du musst nie mehr Rechnungen bezahlen'],answer:0,explain:'Die Verwertung von Vermögen, die Kosten und die öffentliche Bekanntmachung gehören zu den Nachteilen.'},
  {id:'6c',lesson:6,q:'Was kann nach einem Privatkonkurs mit alten Forderungen passieren?',options:['Sie werden auf den Arbeitgeber übertragen','Sie dürfen nie wieder geltend gemacht werden','Bei neuem Vermögen können sie wieder durchgesetzt werden'],answer:2,explain:'Unter den gesetzlichen Voraussetzungen können alte Forderungen bei neuem Vermögen erneut durchgesetzt werden. Neue Schulden sind vom besonderen Schutz nicht erfasst.'},
  {id:'7a',lesson:7,q:'Welches Beispiel beschreibt eine Schuldenspirale?',options:['Für einen Kauf zuerst sparen','Für alte Rechnungen neue Schulden aufnehmen, während die Belastung wächst','Jahresrechnungen monatlich einplanen'],answer:1,explain:'Neue Schulden lösen die alte Budgetlücke oft nicht. Mehr Rückzahlungen, Zinsen und weitere Kosten können die Lage verschärfen.'},
  {id:'7b',lesson:7,q:'Rechnungen bleiben ungeöffnet. Was ist ein sinnvoller erster Schritt?',options:['Die Briefe wegwerfen','Eine weitere Kreditkarte beantragen','Öffnen, Überblick schaffen und bei Bedarf früh Hilfe holen'],answer:2,explain:'Fristen und Beträge zu kennen hilft dir, zu handeln. Sprich früh mit der Rechnungsstelle oder einer Schuldenberatung.'},
  {id:'7c',lesson:7,q:'Warum schränken mehrere Ratenkäufe deinen Spielraum ein?',options:['Ein Teil des zukünftigen Einkommens ist schon verplant','Raten werden immer automatisch erlassen','Dein Lohn steigt dadurch sofort'],answer:0,explain:'Jede Rate ist eine Verpflichtung für später. Zusammen können kleine Raten einen grossen Teil deines Budgets beanspruchen.'},
  {id:'8a',lesson:8,q:'Ein Jahresabo kostet CHF 240. Welche monatliche Rückstellung passt?',options:['CHF 10','CHF 20','CHF 40'],answer:1,explain:'CHF 240 ÷ 12 Monate = CHF 20 pro Monat. So ist die Jahresrechnung von Anfang an im Budget.'},
  {id:'8b',lesson:8,q:'Weshalb kann «Jetzt kaufen, später bezahlen» zur Falle werden?',options:['Die Zahlung wird leicht vergessen oder im Budget nicht eingeplant','Du musst den Kaufpreis nie bezahlen','Der Artikel wird automatisch billiger'],answer:0,explain:'Die Verpflichtung entsteht beim Kauf, auch wenn die Rechnung erst später fällig wird.'},
  {id:'8c',lesson:8,q:'Drei Abos kosten CHF 12, CHF 18 und CHF 20 pro Monat. Was kosten sie zusammen pro Jahr?',options:['CHF 50','CHF 500','CHF 600'],answer:2,explain:'12 + 18 + 20 = CHF 50 pro Monat. 50 × 12 = CHF 600 im Jahr.'},
  {id:'9a',lesson:9,q:'Gehört dir das Auto nach Zahlung aller Leasingraten automatisch?',options:['Ja, immer','Nein, eine Übernahme muss gesondert geregelt sein','Ja, wenn du alle Betriebskosten bezahlt hast'],answer:1,explain:'Leasing gibt dir ein Nutzungsrecht. Während des Leasings gehört das Auto grundsätzlich der Leasinggesellschaft.'},
  {id:'9b',lesson:9,q:'Warum kann ein Leasingvertrag auch bei tiefer Monatsrate teuer werden?',options:['Weil zusätzlich Betriebskosten und mögliche weitere Zahlungen anfallen','Weil Betriebskosten immer in der Rate enthalten sind','Weil die Laufzeit keine Rolle spielt'],answer:0,explain:'Zur Rate kommen zum Beispiel Versicherung, Treibstoff, Unterhalt und eine allfällige Sonderzahlung. Entscheidend ist die Gesamtbelastung.'},
  {id:'9c',lesson:9,q:'Dein Einkommen sinkt während eines Leasings. Was gilt grundsätzlich?',options:['Der Vertrag endet automatisch kostenlos','Die Leasinggesellschaft bezahlt deinen Lebensunterhalt','Die Zahlungsverpflichtungen bleiben bestehen'],answer:2,explain:'Das ist die langfristige Bindung: Weniger Einkommen hebt den Vertrag nicht einfach auf. Eine vorzeitige Beendigung kann teuer werden.'},
  {id:'1d',lesson:1,q:'Dein Nettolohn beträgt CHF 1’100. Der Betrieb verrechnet einen früheren Lohnvorschuss von CHF 100. Sonst nichts. Wie hoch ist die Auszahlung?',options:['CHF 1’100','CHF 1’000','CHF 1’200'],answer:1,explain:'Der Vorschuss wurde schon ausbezahlt. CHF 1’100 − CHF 100 = CHF 1’000 werden diesmal überwiesen.'},
  {id:'2d',lesson:2,q:'AHV-pflichtiger Lohn CHF 1’000: Du zahlst CHF 53 AHV/IV/EO. Was gilt für die CHF 53 Arbeitgeberanteil?',options:['Sie werden dir zusätzlich abgezogen','Sie sind bereits in deinen CHF 53 enthalten','Der Betrieb bezahlt sie zusätzlich aus eigenen Mitteln'],answer:2,explain:'Du trägst 5,3 %, der Betrieb ebenfalls 5,3 %. Nur dein Anteil wird von deinem Lohn abgezogen.'},
  {id:'2e',lesson:2,q:'Wie hoch sind 2026 AHV/IV/EO und ALV zusammen für einen beitragspflichtigen Arbeitnehmer unterhalb der ALV-Grenze?',options:['6,4 %','12,8 %','5,3 %'],answer:0,explain:'5,3 % AHV/IV/EO + 1,1 % ALV = 6,4 %. Andere Abzüge kommen gegebenenfalls dazu. 12,8 % sind beide Seiten zusammen.'},
  {id:'2f',lesson:2,q:'Ab welcher Arbeitszeit besteht grundsätzlich NBU-Schutz über den gleichen Arbeitgeber?',options:['Ab acht Stunden pro Monat','Ab acht Stunden pro Woche','Erst ab einer Vollzeitstelle'],answer:1,explain:'Massgebend sind mindestens acht Wochenstunden beim gleichen Arbeitgeber. Die NBU-Prämie kann auch bei einem 16-Jährigen abgezogen werden.'},
  {id:'2g',lesson:2,q:'Was versichert die obligatorische Pensionskasse zunächst, wenn die Alters- und Lohnvoraussetzungen erfüllt sind?',options:['Nur Freizeitunfälle','Schon ab 16 automatisch alle Altersleistungen','Tod und Invalidität; obligatorisches Alterssparen beginnt später'],answer:2,explain:'Die obligatorische Risikoversicherung beginnt frühestens im Jahr des 18. Geburtstags bei entsprechendem Lohn. Obligatorisches Alterssparen beginnt im Jahr des 25. Geburtstags.'},
  {id:'3d',lesson:3,q:'Wie berechnest du 5,3 % von CHF 1’200?',options:['1’200 × 5,3 ÷ 100 = CHF 63.60','1’200 ÷ 5,3 = rund CHF 226.42','1’200 − 5,3 = CHF 1’194.70'],answer:0,explain:'Ein Prozentsatz wird durch 100 geteilt und mit dem Grundbetrag multipliziert. CHF 1’200 × 0,053 = CHF 63.60.'},
  {id:'4d',lesson:4,q:'Welches Paar unterscheidet Ursache und mögliche Folge richtig?',options:['Ursache: Betreibung. Folge: immer mehr Lohn.','Ursache: Einkommen fällt weg. Folge: offene Rechnungen können zu Betreibungen führen.','Ursache: Rückstellung. Folge: zwangsläufig Schulden.'],answer:1,explain:'Einkommensverlust kann eine Budgetlücke auslösen. Unbezahlte fällige Rechnungen können dann eine Betreibung nach sich ziehen.'},
  {id:'5d',lesson:5,q:'Welche Reihenfolge passt zum vereinfachten Privatkonkursverfahren?',options:['Verlustscheine → Gerichtsgesuch → Vermögen verwerten','Vermögen verteilen → Einigung prüfen → Gericht entscheidet','Einigung prüfen → Gerichtsgesuch und Prüfung → Eröffnung → Verwertung und Verteilung'],answer:2,explain:'Nach dem Prüfen von Alternativen folgen Gesuch und Gerichtsprüfung. Erst nach der Eröffnung wickelt das Konkursamt das Verfahren ab.'},
  {id:'5e',lesson:5,q:'Welche Aussage zum Privatkonkurs passt zum geltenden Recht?',options:['Art. 191 SchKG ist wichtig; das Gericht prüft Voraussetzungen und die Kosten müssen gedeckt werden','Ein hohes Schuldenkonto genügt immer für eine automatische Bewilligung','Der Arbeitgeber bewilligt den Konkurs und bezahlt sämtliche Verfahrenskosten'],answer:0,explain:'Das Gesuch wird gerichtlich geprüft. Einigungsmöglichkeiten und Finanzierung des Verfahrens sind wichtige Punkte; eine automatische Bewilligung gibt es nicht.'},
  {id:'6d',lesson:6,q:'Eine Person hat nach einem durchgeführten Konkurs keine Ersparnisse, könnte mit ihrem Einkommen aber Vermögen bilden. Sind alte Forderungen deshalb sicher ausgeschlossen?',options:['Ja, nur ein hohes Bankguthaben zählt','Nein, auch vermögensbildendes Einkommen kann relevant sein','Ja, ein Konkurs beendet die alten Forderungen immer'],answer:1,explain:'Neues Vermögen kann auch aufgrund eines Einkommens angenommen werden, mit dem Vermögen gebildet werden könnte. Fehlende Ersparnisse allein schützen nicht sicher.'},
  {id:'7d',lesson:7,q:'Eine alte Rate fehlt dir jeden Monat im Budget. Ein neuer Kredit würde die Rechnung heute bezahlen. Was löst die wiederkehrende Lücke am ehesten?',options:['Eine zweite Rate zusätzlich übernehmen','Die Rechnung ungeöffnet liegen lassen','Einnahmen und Ausgaben prüfen und eine tragfähige Lösung suchen'],answer:2,explain:'Ein weiterer Kredit verändert das Grundproblem nicht und schafft neue Rückzahlungen. Ein tragfähiges Budget und gegebenenfalls Beratung setzen bei der Ursache an.'},
  {id:'8d',lesson:8,q:'Für alle Raten zusammen stehen dir CHF 150 pro Monat zur Verfügung. Bisherige Raten: CHF 35, CHF 45 und CHF 50. Eine weitere Rate von CHF 30 käme dazu. Was stimmt?',options:['Dann sind es CHF 160 Raten; das übersteigt den Spielraum','Die neue Rate passt, weil CHF 30 weniger als CHF 150 sind','Es bleiben CHF 120 Spielraum, weil nur die neue Rate zählt'],answer:0,explain:'35 + 45 + 50 + 30 = CHF 160. Alle Verpflichtungen zählen zusammen, nicht nur die neu beworbene Rate.'},
  {id:'9d',lesson:9,q:'Was gilt bei einem Leasingvertrag, der dem KKG untersteht, für den Widerruf?',options:['Es gibt grundsätzlich eine schriftliche Widerrufsmöglichkeit von 14 Tagen ab Erhalt der Vertragskopie','Man kann während der ganzen Laufzeit ohne Kosten widerrufen','Nur ein mündlicher Widerruf am ersten Tag ist möglich'],answer:0,explain:'Das KKG sieht eine schriftliche Widerrufsmöglichkeit von 14 Tagen ab Erhalt der Vertragskopie vor. Spätere Kündigung ist etwas anderes und kann kosten.'},
  {id:'9e',lesson:9,q:'Was bedeutet vorzeitige Kündigung bei einem Leasingvertrag unter dem KKG?',options:['Die Kündigung ist immer ausgeschlossen','Sie ist mit gesetzlichen Fristen möglich; die vertragliche Entschädigungstabelle bleibt wichtig','Sie ist nach dem ersten Monat immer kostenlos'],answer:1,explain:'Kündigung kann möglich sein und trotzdem hohe Nachzahlungen auslösen. Prüfe Frist und Entschädigungstabelle im Vertrag.'},
  {id:'9f',lesson:9,q:'Eine 16-jährige Person will einen Leasingvertrag unter dem KKG unterschreiben. Was ist für die Gültigkeit zusätzlich nötig?',options:['Die Zustimmung des Lehrbetriebs','Nur ein eigenes Bankkonto','Die schriftliche Zustimmung der gesetzlichen Vertretung spätestens bei der Unterzeichnung'],answer:2,explain:'Art. 13 KKG verlangt bei Minderjährigen die schriftliche Zustimmung der gesetzlichen Vertretung. Eine Unterschrift allein oder das eigene Konto ersetzen sie nicht.'},
  {id:'n1',lesson:3,type:'number',q:'Du bist 16, Brutto CHF 1’000. Einziger Abzug: angenommene 1 % NBU. Wie viel netto?',answer:990,unit:'CHF',hint:'Keine weiteren Abzüge und keine Spesen.',explain:'1 % von CHF 1’000 sind CHF 10. Mit 16 fallen noch keine AHV/IV/EO- und ALV-Beiträge an. 1’000 − 10 = CHF 990.'},
  {id:'n2',lesson:8,type:'number',q:'Vier Raten von je CHF 35 werden jeden Monat fällig. Wie hoch ist die monatliche Gesamtbelastung?',answer:140,unit:'CHF',hint:'Gesucht ist die Summe aller vier Monatsraten.',explain:'4 × CHF 35 = CHF 140 pro Monat. Auch kleine Einzelraten können zusammen viel ausmachen.'},
  {id:'n3',lesson:9,type:'number',q:'Leasing: 48 × CHF 250 Raten, 48 × CHF 300 Betriebskosten, CHF 3’000 Sonderzahlung. Durchschnittliche Gesamtausgaben pro Monat?',answer:612.5,unit:'CHF',hint:'Zähle alle Ausgaben zusammen und teile durch 48. Keine spätere Übernahme enthalten.',explain:'12’000 + 14’400 + 3’000 = CHF 29’400. Geteilt durch 48 ergibt das CHF 612.50 pro Monat.'}
];
